-- RATIFIED BY GOVERNOR YARIV 2026-08-25: Deduplicated Backlog Migration (10 Items)
-- Zero Hardcoded UUID Literals. Subquery resolves customer_accounts.company_name = 'CISEM Platform' in PostgreSQL.
ALTER TABLE backlog_registry ADD COLUMN IF NOT EXISTS customer_account_id UUID REFERENCES customer_accounts(id) ON DELETE CASCADE;
ALTER TABLE backlog_registry ADD COLUMN IF NOT EXISTS subject_category VARCHAR(50) DEFAULT 'SYSTEM_SPINE' NOT NULL;
ALTER TABLE backlog_registry ADD COLUMN IF NOT EXISTS unblocks_count INTEGER DEFAULT 0;
ALTER TABLE backlog_registry ADD COLUMN IF NOT EXISTS occurrence_count INTEGER DEFAULT 1;
ALTER TABLE backlog_registry ADD COLUMN IF NOT EXISTS dependencies TEXT[] DEFAULT '{}'::text[];
ALTER TABLE backlog_registry ADD COLUMN IF NOT EXISTS reconnect_trigger TEXT;
ALTER TABLE backlog_registry DROP CONSTRAINT IF EXISTS check_impact_level;
ALTER TABLE backlog_registry ADD CONSTRAINT check_impact_level CHECK (impact_level IN ('LOW', 'MEDIUM', 'HIGH', 'KEYSTONE'));

INSERT INTO backlog_registry (serial_code, subject_category, title, context, tags, status, impact_level, unblocks_count, occurrence_count, customer_account_id, dependencies, reconnect_trigger) VALUES ('BACKLOG-SYS-001', 'SYSTEM_SPINE', 'Naked Numbers Class -- Context/Reasoning missing for raw numbers', 'ATV Naked Number Audit detected 20 occurrences of raw numbers across documentation files without surrounding context keywords. Aggregated into a single defect class item.', ARRAY['[AUDIT.RIGIDITY]', '[DOCUMENTATION.CONTEXT]']::text[], 'backlog_raw', 'MEDIUM', 3, 20, (SELECT id FROM customer_accounts WHERE company_name = 'CISEM Platform' LIMIT 1), ARRAY['CISEM-IP-20260806-CONTEXT-ADAPTIVE-V1.0']::text[], 'Document number contextualization linter clean pass') ON CONFLICT (serial_code) DO UPDATE SET subject_category = EXCLUDED.subject_category, title = EXCLUDED.title, context = EXCLUDED.context, tags = EXCLUDED.tags, status = EXCLUDED.status, impact_level = EXCLUDED.impact_level, unblocks_count = EXCLUDED.unblocks_count, occurrence_count = EXCLUDED.occurrence_count, customer_account_id = EXCLUDED.customer_account_id, dependencies = EXCLUDED.dependencies, reconnect_trigger = EXCLUDED.reconnect_trigger;
INSERT INTO backlog_registry (serial_code, subject_category, title, context, tags, status, impact_level, unblocks_count, occurrence_count, customer_account_id, dependencies, reconnect_trigger) VALUES ('BACKLOG-SYS-002', 'SYSTEM_SPINE', 'Underactivated Mechanisms Class -- 7 mechanisms underactivated', 'ATV audit detected 7 compiler and sync mechanisms with underactivated trigger counts (CISEM-GATE-V2, CISEM-SYNC-V1.1, CISEM-WATCHER-LOCK, CISEM-ATV-V1, CISEM-TURN-COUNTER, CISEM-PERSONA-AUDITOR, CISEM-REGISTRY). Aggregated into single mechanism activation item.', ARRAY['[IMPROVEMENT.GAP]', '[ACTIVATION.UNDERACTIVATED]']::text[], 'backlog_raw', 'KEYSTONE', 7, 7, (SELECT id FROM customer_accounts WHERE company_name = 'CISEM Platform' LIMIT 1), ARRAY['CISEM-IP-20260806-ANTITHEATER-V1.0', 'CISEM-IP-20260806-UNDERACTIVATED-V1.0']::text[], '100% trigger activation targets met across all 7 mechanisms') ON CONFLICT (serial_code) DO UPDATE SET subject_category = EXCLUDED.subject_category, title = EXCLUDED.title, context = EXCLUDED.context, tags = EXCLUDED.tags, status = EXCLUDED.status, impact_level = EXCLUDED.impact_level, unblocks_count = EXCLUDED.unblocks_count, occurrence_count = EXCLUDED.occurrence_count, customer_account_id = EXCLUDED.customer_account_id, dependencies = EXCLUDED.dependencies, reconnect_trigger = EXCLUDED.reconnect_trigger;
INSERT INTO backlog_registry (serial_code, subject_category, title, context, tags, status, impact_level, unblocks_count, occurrence_count, customer_account_id, dependencies, reconnect_trigger) VALUES ('BACKLOG-SYS-003', 'PERFORMANCE', 'Edge Cache Caching Lag for UI theme swaps', 'Switching themes in dashboard portal has latency lag on Vercel Edge. Needs client hydration bypass.', ARRAY['[PERFORMANCE.CACHE]', '[UI.THEME]']::text[], 'backlog_raw', 'HIGH', 2, 1, (SELECT id FROM customer_accounts WHERE company_name = 'CISEM Platform' LIMIT 1), ARRAY['CISEM-IP-20260825-MASTER-CONSOLIDATED-V2']::text[], 'Edge cache hydration latency < 50ms') ON CONFLICT (serial_code) DO UPDATE SET subject_category = EXCLUDED.subject_category, title = EXCLUDED.title, context = EXCLUDED.context, tags = EXCLUDED.tags, status = EXCLUDED.status, impact_level = EXCLUDED.impact_level, unblocks_count = EXCLUDED.unblocks_count, occurrence_count = EXCLUDED.occurrence_count, customer_account_id = EXCLUDED.customer_account_id, dependencies = EXCLUDED.dependencies, reconnect_trigger = EXCLUDED.reconnect_trigger;
